/**
 * @name Insecure use of urllib without scheme or validation
 * @description Detect construction of URLs from untrusted input for urllib calls
 * @kind path-problem
 * @problem.severity warning
 * @id py/referencing-url-taint
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UrlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("urllib").getMember("request").getMember(["urlopen", "Request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UrlFlow = TaintTracking::Global<UrlConfig>;
import UrlFlow::PathGraph

from UrlFlow::PathNode source, UrlFlow::PathNode sink
where UrlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data used to construct URL for urllib call $@.", source.getNode(), "untrusted URL"

/**
 * @name Remote data to file system access
 * @description Detects flows from remote/JSON inputs into file path arguments
 * @kind path-problem
 * @problem.severity error
 * @id py/referencing/remote-to-filesystem
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module RemoteToFsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("urllib").getMember(["request", "parse"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module RemoteToFsFlow = TaintTracking::Global<RemoteToFsConfig>;
import RemoteToFsFlow::PathGraph

from RemoteToFsFlow::PathNode source, RemoteToFsFlow::PathNode sink
where RemoteToFsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Remote data reaches file/URL-related argument $@.", source.getNode(), "remote data"

/**
 * @name Remote input flowing into code execution (stub)
 * @description Stub query that sets up taint tracking from remote-flow sources to code execution sinks.
 * @kind problem
 * @problem.severity medium
 * @id custom.python.remote-to-code-exec.stub
 * @tags security
 *       external/cwe/cwe-94
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module RemoteToExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink instanceof CodeExecution
  }
}

module RemoteToExecFlow = TaintTracking::Global<RemoteToExecConfig>;

predicate remoteTaintReachesExec(DataFlow::Node source, DataFlow::Node sink) {
  RemoteToExecFlow::flow(source, sink)
}

from DataFlow::Node source, DataFlow::Node sink
where remoteTaintReachesExec(source, sink)
select sink, "Remote input may flow into code execution (CWE-94)."
